import org.junit.jupiter.api.Test;

class ConservativeQueryExecutionTest {

	@Test
	void defaultReplayProducesFirstMatchWithoutReadingRemainingRightRows() {
		AtomicInteger rightRows = new AtomicInteger();
		AtomicInteger rightOpens = new AtomicInteger();
		QueryEvaluationStep left = bindings -> new CloseableIteratorIteration<>(List.of(row("left", 1),
				row("left", 2)).iterator());
		QueryEvaluationStep right = bindings -> {
			rightOpens.incrementAndGet();
			return new LookAheadIteration<>() {
				private final Iterator<BindingSet> rows = List.of(row("right", 10), row("right", 20),
						row("right", 30)).iterator();

				@Override
				protected BindingSet getNextElement() {
					if (!rows.hasNext()) {
						return null;
					}
					rightRows.incrementAndGet();
					return rows.next();
				}

				@Override
				protected void handleClose() {
				}
			};
		};
		try (var replay = new MaterializedReplayJoinIterator(left, right, null, EmptyBindingSet.getInstance(), false)) {
			assertTrue(replay.hasNext());
			assertEquals("10", replay.next().getValue("right").stringValue());
			assertEquals(1, rightRows.get(), "default replay must not prefetch the rest of an independent RHS");
			int remaining = 0;
			while (replay.hasNext()) {
				replay.next();
				remaining++;
			}
			assertEquals(5, remaining);
			assertEquals(3, rightRows.get());
			assertEquals(1, rightOpens.get());
			assertFalse(replay.hasNext());
		}
	}

	@Test
	void defaultCalendarOrderPreservesEqualityForDifferentSpellingsOfSameInstant() {
		var vf = SimpleValueFactory.getInstance();
		var utc = vf.createLiteral("2026-01-01T12:00:00Z", CoreDatatype.XSD.DATETIME);
		var offset = vf.createLiteral("2026-01-01T13:00:00+01:00", CoreDatatype.XSD.DATETIME);
		var comparator = new ValueComparator();
		assertEquals(0, comparator.compare(utc, offset));
		assertEquals(0, comparator.compare(offset, utc));
	}

	@Test
	void normalReplayExhaustionClosesTheOwnedRightStreamExactlyOnce() {
		AtomicInteger closes = new AtomicInteger();
		QueryEvaluationStep left = bindings -> new CloseableIteratorIteration<>(List.of(row("left", 1)).iterator());
		QueryEvaluationStep right = bindings -> new CloseableIteration<>() {
			private final Iterator<BindingSet> rows = List.of(row("right", 10), row("right", 20)).iterator();

			@Override
			public boolean hasNext() {
				return rows.hasNext();
			}

			@Override
			public BindingSet next() {
				return rows.next();
			}

			@Override
			public void close() {
				closes.incrementAndGet();
			}
		};
		try (var replay = new MaterializedReplayJoinIterator(left, right, null, EmptyBindingSet.getInstance(), false)) {
			int rows = 0;
			while (replay.hasNext()) {
				replay.next();
				rows++;
			}
			assertEquals(2, rows);
		}
		assertEquals(1, closes.get(), "the replay owns and closes the RHS once even when its close is not idempotent");
	}

	@Test
	void emptyLeftStillDrainsTheRightWithoutRetainingUnusableRows() {
		AtomicInteger rightRows = new AtomicInteger();
		AtomicInteger retainedRows = new AtomicInteger();
		QueryEvaluationStep left = bindings -> new CloseableIteratorIteration<>(List.<BindingSet>of().iterator());
		QueryEvaluationStep right = bindings -> new LookAheadIteration<>() {
			private int position;

			@Override
			protected BindingSet getNextElement() {
				if (position == 3) {
					return null;
				}
				rightRows.incrementAndGet();
				return row("right", position++);
			}

			@Override
			protected void handleClose() {
			}
		};
		DefaultCollectionFactory factory = new DefaultCollectionFactory() {
			@Override
			public <K, V> Map<K, V> createMap() {
				return new HashMap<>() {
					@Override
					public V put(K key, V value) {
						retainedRows.incrementAndGet();
						return super.put(key, value);
					}
				};
			}
		};
		try (var replay = new MaterializedReplayJoinIterator(left, right, null, EmptyBindingSet.getInstance(), false,
				List.of(), () -> factory)) {
			assertFalse(replay.hasNext());
		}
		assertEquals(3, rightRows.get());
		assertEquals(0, retainedRows.get());
	}

	private static BindingSet row(String name, int value) {
		MapBindingSet row = new MapBindingSet(1);
		row.addBinding(name, SimpleValueFactory.getInstance().createLiteral(value));
		return row;
	}
}
